import networkx as nx
from itertools import combinations

g = nx.Graph()
g.add_nodes_from(range(15))

for u, v in combinations(range(15), 2):
    if len(list(nx.common_neighbors(g, u, v))) >= 2:
        g.add_edge(u, v)

if len(g.edges) >= 22 and nx.girth(g) >= 7 and nx.algorithms.coloring.greedy_color(g).max() + 1 <= 4:
    print("SATISFIABLE")
    print(list(g.edges))
else:
    print("UNSATISFIABLE")
